CREATE TABLE IF NOT EXISTS wf_workflows (id TEXT PRIMARY KEY, title TEXT NOT NULL, source TEXT, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS wf_workflows_source ON wf_workflows(source);
CREATE TABLE IF NOT EXISTS wf_cards (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL,
  status TEXT NOT NULL, decision TEXT, x REAL NOT NULL, y REAL NOT NULL, expanded INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wf_cards_workflow ON wf_cards(workflow_id);
CREATE TABLE IF NOT EXISTS wf_edges (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, source TEXT NOT NULL, target TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wf_edges_workflow ON wf_edges(workflow_id);
CREATE TABLE IF NOT EXISTS wf_messages (id TEXT PRIMARY KEY, card_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wf_messages_card ON wf_messages(card_id, created_at);
CREATE TABLE IF NOT EXISTS wf_link_previews (url TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT, description TEXT, image TEXT, site TEXT, fetched_at TEXT NOT NULL);
`;

export function ensureSchema(d: DatabaseSync) {
  d.exec(DDL);
}
import { DatabaseSync } from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';

// One SQLite file shared by all three PoCs (pocs/.data/super-planer.db) so step1 → workflow-view → plan-doc can hand data over.
const file = process.env.SUPER_PLANER_DB ?? path.join(process.cwd(), '..', '.data', 'super-planer.db');
const g = globalThis as unknown as { __spdb?: DatabaseSync };

export function db(): DatabaseSync {
  if (!g.__spdb) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const d = new DatabaseSync(file);
    d.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 3000; PRAGMA foreign_keys = ON;');
    g.__spdb = d;
  }
  return g.__spdb;
}

export function tableExists(name: string): boolean {
  return !!db().prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name);
}
// Small helpers for route handlers: JSON-only bodies (a cross-site form post cannot send application/json without a preflight).

export const bad = (error: string, status = 400) => Response.json({ error }, { status });

export async function jsonBody(req: Request): Promise<Record<string, unknown> | null> {
  if (!(req.headers.get('content-type') ?? '').toLowerCase().startsWith('application/json')) return null;
  try {
    const b: unknown = await req.json();
    return b && typeof b === 'object' && !Array.isArray(b) ? (b as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

/** Trimmed string within [min, max] chars, else null. */
export function str(v: unknown, min: number, max: number): string | null {
  if (typeof v !== 'string') return null;
  const s = v.trim();
  return s.length >= min && s.length <= max ? s : null;
}

export const num = (v: unknown): number | null => (typeof v === 'number' && Number.isFinite(v) && Math.abs(v) < 1e6 ? v : null);
// URL helpers shared by the chat renderer (client) and the plan-doc hand-off (server).

const URL_RE = /https?:\/\/[A-Za-z0-9\-._~:/?#@!$&*+,;=%()]+/g;
const IMAGE_EXT = /\.(png|jpe?g|gif|webp|avif|svg)$/i;
const IMAGE_HOSTS = new Set(['picsum.photos', 'images.unsplash.com']);

/** Trim sentence punctuation and an unbalanced closing paren (markdown `[t](url)`, "(see https://x)"). */
export function trimUrl(raw: string): string {
  let u = raw.replace(/[.,;:!?*]+$/, '');
  while (u.endsWith(')') && (u.match(/\(/g)?.length ?? 0) < (u.match(/\)/g)?.length ?? 0)) {
    u = u.slice(0, -1).replace(/[.,;:!?*]+$/, '');
  }
  return u;
}

/** Every distinct http(s) URL in the text, in order of appearance. */
export function extractUrls(text: string): string[] {
  const out: string[] = [];
  for (const m of text.matchAll(URL_RE)) {
    const u = trimUrl(m[0]);
    if (!isHttpUrl(u) || out.includes(u)) continue;
    out.push(u);
  }
  return out;
}

export function isHttpUrl(s: string): boolean {
  try {
    const u = new URL(s);
    return (u.protocol === 'http:' || u.protocol === 'https:') && !!u.hostname;
  } catch {
    return false;
  }
}

/** Image by file extension or by a known image host; such URLs render as <img> and are never fetched server-side. */
export function isImageUrl(s: string): boolean {
  try {
    const u = new URL(s);
    return IMAGE_EXT.test(u.pathname) || IMAGE_HOSTS.has(u.hostname);
  } catch {
    return false;
  }
}

export function hostOf(s: string): string {
  try {
    return new URL(s).hostname.replace(/^www\./, '');
  } catch {
    return s;
  }
}
// Server-side link preview with an SSRF guard. Every hop (first URL and each redirect) is re-checked,
// and the DNS answer is checked inside the socket's own lookup, so a rebinding name cannot slip past.
import http from 'node:http';
import https from 'node:https';
import dns from 'node:dns';
import net from 'node:net';
import zlib from 'node:zlib';
import type { Readable } from 'node:stream';

export type Preview = {
  url: string;
  kind: 'image' | 'page';
  title: string | null;
  description: string | null;
  image: string | null;
  site: string | null;
};

const MAX_BYTES = 1024 * 1024;
const MAX_REDIRECTS = 3;
const TIMEOUT_MS = 5000;

// Two lists: a v6 rule like ::ffff:0:0/96 would otherwise also match every plain IPv4 address.
const blocked4 = new net.BlockList();
const blocked6 = new net.BlockList();
const embeds4 = new net.BlockList(); // v6 prefixes whose last 32 bits are an IPv4 address: judge that address
for (const [a, p] of [
  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16], ['172.16.0.0', 12],
  ['192.0.0.0', 24], ['192.0.2.0', 24], ['192.88.99.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
] as const) blocked4.addSubnet(a, p, 'ipv4');
for (const [a, p] of [
  ['::', 96], // unspecified, loopback, IPv4-compatible
  ['64:ff9b:1::', 48], ['100::', 64], ['2001::', 32], ['2001:db8::', 32], ['2002::', 16],
  ['fc00::', 7], ['fe80::', 10], ['fec0::', 10], ['ff00::', 8],
] as const) blocked6.addSubnet(a, p, 'ipv6');
embeds4.addSubnet('::ffff:0:0', 96, 'ipv6'); // IPv4-mapped
embeds4.addSubnet('64:ff9b::', 96, 'ipv6'); // NAT64 well-known prefix (DNS64 networks answer with it)

/** True for anything that is not a public unicast address (loopback, private, link-local/metadata, CGNAT, …). */
export function isBlockedIp(ip: string): boolean {
  const v = net.isIP(ip);
  if (!v) return true;
  if (v === 4) return blocked4.check(ip, 'ipv4');
  if (embeds4.check(ip, 'ipv6')) {
    // URL normalises to compressed hex, so the last two groups are the low 32 bits ("::" → 0)
    const g = new URL(`http://[${ip}]/`).hostname.slice(1, -1).split(':').slice(-2).map((x) => parseInt(x || '0', 16));
    return isBlockedIp(`${g[0] >> 8}.${g[0] & 255}.${g[1] >> 8}.${g[1] & 255}`);
  }
  return blocked6.check(ip, 'ipv6');
}

class BlockedError extends Error {}

function assertAllowed(u: URL) {
  if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new BlockedError(`protocol ${u.protocol} not allowed`);
  if (u.username || u.password) throw new BlockedError('credentials in URL not allowed');
  if (u.port && u.port !== '80' && u.port !== '443') throw new BlockedError(`port ${u.port} not allowed`);
  const host = u.hostname.replace(/^\[|\]$/g, '');
  if (net.isIP(host) && isBlockedIp(host)) throw new BlockedError(`address ${host} not allowed`);
}

type LookupCb = (err: NodeJS.ErrnoException | null, address: string | dns.LookupAddress[], family?: number) => void;
const guardedLookup = ((hostname: string, options: dns.LookupOptions, cb: LookupCb) => {
  dns.lookup(hostname, { ...options, all: true }, (err, addrs) => {
    if (err) return cb(err, '');
    const bad = addrs.find((a) => isBlockedIp(a.address));
    if (!addrs.length || bad) return cb(new BlockedError(`${hostname} resolves to a blocked address`), '');
    if (options.all) cb(null, addrs);
    else cb(null, addrs[0].address, addrs[0].family);
  });
}) as unknown as net.LookupFunction;

function get(u: URL, signal: AbortSignal): Promise<http.IncomingMessage> {
  return new Promise((resolve, reject) => {
    const req = (u.protocol === 'https:' ? https : http).get(u, {
      agent: false,
      lookup: guardedLookup,
      signal,
      headers: {
        'user-agent': 'SuperPlanerLinkPreview/0.1',
        accept: 'text/html,application/xhtml+xml;q=0.9,*/*;q=0.5',
        'accept-encoding': 'gzip, deflate, br',
      },
    });
    req.on('response', resolve);
    req.on('error', reject);
  });
}

function readCapped(res: http.IncomingMessage): Promise<Buffer> {
  const enc = String(res.headers['content-encoding'] ?? '').toLowerCase();
  const stream: Readable =
    enc === 'gzip' ? res.pipe(zlib.createGunzip())
    : enc === 'deflate' ? res.pipe(zlib.createInflate())
    : enc === 'br' ? res.pipe(zlib.createBrotliDecompress())
    : res;
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      res.destroy();
      resolve(Buffer.concat(chunks).subarray(0, MAX_BYTES));
    };
    stream.on('data', (c: Buffer) => {
      chunks.push(c);
      size += c.length;
      if (size >= MAX_BYTES) finish(); // shortcut: parse only the first 1MB, enough for <head>
    });
    stream.on('end', finish);
    const fail = (e: Error) => {
      if (done) return;
      done = true;
      reject(e);
    };
    stream.on('error', fail);
    if (stream !== res) res.on('error', fail);
  });
}

function decode(buf: Buffer, contentType: string): string {
  const sniff = buf.subarray(0, 2048).toString('latin1');
  const label =
    /charset=["']?([\w-]+)/i.exec(contentType)?.[1] ?? /<meta[^>]+charset=["']?([\w-]+)/i.exec(sniff)?.[1] ?? 'utf-8';
  try {
    return new TextDecoder(label).decode(buf);
  } catch {
    return new TextDecoder('utf-8').decode(buf);
  }
}

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };
function decodeEntities(s: string): string {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+|#39);/gi, (m, e: string) => {
    if (e[0] === '#') {
      const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(n) && n > 0 && n < 0x110000 ? String.fromCodePoint(n) : m;
    }
    return ENTITIES[e.toLowerCase()] ?? m;
  });
}

function attr(tag: string, name: string): string | null {
  const m = new RegExp(`\\s${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s"'>]+))`, 'i').exec(tag);
  return m ? (m[1] ?? m[2] ?? m[3]) : null;
}

const clip = (s: string | undefined | null, n: number) => {
  const t = s?.replace(/\s+/g, ' ').trim();
  return t ? (t.length > n ? `${t.slice(0, n - 1)}…` : t) : null;
};

/** og:/twitter:/<title> metadata from an HTML string. Relative og:image resolves against `base`. */
export function parseMeta(html: string, base: URL): Omit<Preview, 'url' | 'kind'> {
  const metas = new Map<string, string>();
  for (const m of html.matchAll(/<meta\b[^>]*>/gi)) {
    const key = (attr(m[0], 'property') ?? attr(m[0], 'name'))?.toLowerCase();
    const content = attr(m[0], 'content');
    if (key && content !== null && !metas.has(key)) metas.set(key, decodeEntities(content));
  }
  const titleTag = /<title[^>]*>([^<]*)<\/title>/i.exec(html)?.[1];
  let image: string | null = null;
  const rawImage = metas.get('og:image') ?? metas.get('og:image:url') ?? metas.get('twitter:image');
  if (rawImage) {
    try {
      const iu = new URL(rawImage, base);
      if (iu.protocol === 'http:' || iu.protocol === 'https:') image = iu.href;
    } catch {
      /* ignore a broken og:image */
    }
  }
  return {
    title: clip(metas.get('og:title') ?? metas.get('twitter:title') ?? (titleTag ? decodeEntities(titleTag) : null), 200),
    description: clip(metas.get('og:description') ?? metas.get('twitter:description') ?? metas.get('description'), 400),
    image,
    site: clip(metas.get('og:site_name'), 80) ?? base.hostname.replace(/^www\./, ''),
  };
}

/** Fetch a page's preview. Throws on a blocked target, a non-2xx, a non-HTML body or a timeout. */
export async function fetchPreview(raw: string): Promise<Preview> {
  let u = new URL(raw);
  const signal = AbortSignal.timeout(TIMEOUT_MS);
  for (let hop = 0; ; hop++) {
    assertAllowed(u);
    const res = await get(u, signal);
    const status = res.statusCode ?? 0;
    if (status >= 300 && status < 400 && res.headers.location) {
      res.resume();
      if (hop >= MAX_REDIRECTS) throw new Error('too many redirects');
      u = new URL(res.headers.location, u);
      continue;
    }
    if (status < 200 || status >= 300) {
      res.resume();
      throw new Error(`HTTP ${status}`);
    }
    const type = String(res.headers['content-type'] ?? '');
    if (/^image\//i.test(type)) {
      res.destroy();
      return { url: raw, kind: 'image', title: null, description: null, image: u.href, site: u.hostname };
    }
    if (!/text\/html|application\/xhtml\+xml/i.test(type)) {
      res.destroy();
      throw new Error(`not HTML (${type || 'no content-type'})`);
    }
    const html = decode(await readCapped(res), type);
    return { url: raw, kind: 'page', ...parseMeta(html, u) };
  }
}

import { randomUUID } from 'node:crypto';
import { db, tableExists } from './db';
import { ensureSchema } from './schema';
import { SEED } from './seed';

export type Status = 'active' | 'frozen' | 'cancelled';
export type Workflow = { id: string; title: string; source: string | null; created_at: string };
export type Card = {
  id: string; workflow_id: string; title: string; description: string; status: Status;
  decision: string | null; x: number; y: number; expanded: boolean; created_at: string;
};
export type Edge = { id: string; workflow_id: string; source: string; target: string };
export type Message = { id: string; card_id: string; role: 'user' | 'agent'; content: string; created_at: string };

const g = globalThis as unknown as { __wfReady?: boolean };

/** The shared DB with workflow-view's tables created and the sample workflow seeded. */
export function wf() {
  const d = db();
  if (!g.__wfReady) {
    ensureSchema(d);
    if (!d.prepare('SELECT 1 FROM wf_workflows LIMIT 1').get()) seed();
    g.__wfReady = true;
  }
  return d;
}

/** BEGIN/COMMIT around fn; node:sqlite has no transaction helper. */
function tx<T>(fn: () => T): T {
  const d = db();
  d.exec('BEGIN IMMEDIATE');
  try {
    const r = fn();
    d.exec('COMMIT');
    return r;
  } catch (e) {
    d.exec('ROLLBACK');
    throw e;
  }
}

const now = () => new Date().toISOString();

// node:sqlite rows have a null prototype and INTEGER flags; normalise once here.
const toCard = (r: Record<string, unknown>): Card => ({
  id: String(r.id), workflow_id: String(r.workflow_id), title: String(r.title), description: String(r.description),
  status: r.status as Status, decision: (r.decision as string | null) ?? null, x: Number(r.x), y: Number(r.y),
  expanded: !!r.expanded, created_at: String(r.created_at),
});
const plain = <T,>(r: unknown) => ({ ...(r as object) }) as T;

export function insertWorkflow(title: string, source: string | null): string {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_workflows (id, title, source, created_at) VALUES (?, ?, ?, ?)').run(id, title, source, now());
  return id;
}

export function insertCard(c: Omit<Card, 'id' | 'created_at' | 'expanded'> & { expanded?: boolean }, at = now()): Card {
  const id = randomUUID();
  db().prepare(
    'INSERT INTO wf_cards (id, workflow_id, title, description, status, decision, x, y, expanded, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
  ).run(id, c.workflow_id, c.title, c.description, c.status, c.decision, c.x, c.y, c.expanded ? 1 : 0, at);
  return { ...c, id, expanded: !!c.expanded, created_at: at };
}

export function insertEdge(workflowId: string, source: string, target: string): Edge {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_edges (id, workflow_id, source, target) VALUES (?, ?, ?, ?)').run(id, workflowId, source, target);
  return { id, workflow_id: workflowId, source, target };
}

export function insertMessage(cardId: string, role: Message['role'], content: string, at = now()): Message {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_messages (id, card_id, role, content, created_at) VALUES (?, ?, ?, ?, ?)').run(id, cardId, role, content, at);
  return { id, card_id: cardId, role, content, created_at: at };
}

export function getCard(id: string): Card | null {
  const r = wf().prepare('SELECT * FROM wf_cards WHERE id = ?').get(id);
  return r ? toCard(r) : null;
}

export function cardMessages(cardId: string): Message[] {
  return wf().prepare('SELECT * FROM wf_messages WHERE card_id = ? ORDER BY created_at, rowid').all(cardId).map((r) => plain<Message>(r));
}

export function getWorkflow(id: string): Workflow | null {
  const r = wf().prepare('SELECT * FROM wf_workflows WHERE id = ?').get(id);
  return r ? plain<Workflow>(r) : null;
}

export function listWorkflows(): Workflow[] {
  return wf().prepare('SELECT * FROM wf_workflows ORDER BY created_at DESC').all().map((r) => plain<Workflow>(r));
}

export function loadWorkflow(id: string) {
  const workflow = getWorkflow(id);
  if (!workflow) return null;
  const d = wf();
  const cards = d.prepare('SELECT * FROM wf_cards WHERE workflow_id = ? ORDER BY created_at, rowid').all(id).map(toCard);
  const edges = d.prepare('SELECT * FROM wf_edges WHERE workflow_id = ?').all(id).map((r) => plain<Edge>(r));
  const messages = d
    .prepare('SELECT m.* FROM wf_messages m JOIN wf_cards c ON c.id = m.card_id WHERE c.workflow_id = ? ORDER BY m.created_at, m.rowid')
    .all(id)
    .map((r) => plain<Message>(r));
  return { workflow, cards, edges, messages };
}

function seed() {
  tx(() => {
    const wid = insertWorkflow(SEED.title, 'seed');
    const ids: Record<string, string> = {};
    const t0 = Date.now() - 60 * 60 * 1000;
    SEED.cards.forEach((c, i) => {
      const at = (k: number) => new Date(t0 + i * 6 * 60 * 1000 + k * 60 * 1000).toISOString();
      const card = insertCard({ workflow_id: wid, title: c.title, description: c.description, status: c.status, decision: c.decision ?? null, x: c.x, y: c.y }, at(0));
      ids[c.key] = card.id;
      c.messages.forEach(([role, content], k) => insertMessage(card.id, role, content, at(k)));
    });
    for (const [a, b] of SEED.edges) insertEdge(wid, ids[a], ids[b]);
  });
}

