        const { card } = await api<{ card: Card }>(`/api/cards/${id}/status`, 'POST', { action });
        patchCard(id, (d) => ({ ...d, card: { ...card, expanded: d.card.expanded, x: d.card.x, y: d.card.y } }));
      } catch (e) {
        fail(e);
      }
    },
    async send(id, content) {
      const r = await api<{ messages: Message[]; error?: string }>(`/api/cards/${id}/messages`, 'POST', { content });
      patchCard(id, (d) => ({ ...d, messages: [...d.messages, ...r.messages] }));
      return { error: r.error };
    },
  }), [rf, patchCard, fail]);

  // Persist the final position of a drag or keyboard nudge (dragging === false), coalescing quick nudges.
  const onNodesChange = useCallback((changes: NodeChange<CardNodeT>[]) => {
    onNodesChangeBase(changes.filter((c) => c.type !== 'remove'));
    for (const c of changes) {
      if (c.type !== 'position' || c.dragging !== false || !c.position) continue;
      const { id } = c;
      const x = Math.round(c.position.x);
      const y = Math.round(c.position.y);
      clearTimeout(timers.current.get(id));
      timers.current.set(id, setTimeout(() => {
        patchCard(id, (d) => ({ ...d, card: { ...d.card, x, y } }));
        api(`/api/cards/${id}`, 'PATCH', { x, y }).catch(fail);
      }, 250));
    }
  }, [onNodesChangeBase, patchCard, fail]);

  const onConnect = useCallback(async (c: Connection) => {
    try {
      const { edge } = await api<{ edge: Edge }>(`/api/workflows/${workflow.id}/edges`, 'POST', { source: c.source, target: c.target });
      setEdges((es) => addEdge({ id: edge.id, source: edge.source, target: edge.target }, es));
    } catch (e) {
      fail(e);
    }
  }, [workflow.id, setEdges, fail]);

  // Cards are never deleted from the canvas; only connectors are.
  const onBeforeDelete: OnBeforeDelete<CardNodeT, FlowEdge> = useCallback(async ({ edges: es }) => ({ nodes: [], edges: es }), []);
  const onEdgesDelete = useCallback((deleted: FlowEdge[]) => {
    for (const e of deleted) {
      api(`/api/edges/${e.id}`, 'DELETE').catch((err) => {
        fail(err);
        setEdges((es) => (es.some((x) => x.id === e.id) ? es : [...es, { id: e.id, source: e.source, target: e.target }]));
      });
    }
  }, [fail, setEdges]);

  const status = new Map(nodes.map((n) => [n.id, n.data.card.status]));
  const shownEdges = edges.map((e) => ({ ...e, className: `edge--${status.get(e.target) ?? 'active'}` }));
  const frozen = nodes.filter((n) => n.data.card.status === 'frozen').length;
  const selectedEdges = edges.filter((e) => e.selected);

  async function addCard(title: string, description: string) {
    const rect = canvasRef.current?.getBoundingClientRect();
    const center = rect ? rf.screenToFlowPosition({ x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }) : { x: 0, y: 0 };
    const offset = nodes.length % 5 * 24; // stack repeated adds visibly instead of exactly on top of each other
    const { card } = await api<{ card: Card }>(`/api/workflows/${workflow.id}/cards`, 'POST', {
      title, description, x: Math.round(center.x - 220 + offset), y: Math.round(center.y - 160 + offset),
    });
    setNodes((ns) => [...ns.map((n) => ({ ...n, selected: false })), { ...toNode(card, []), selected: true }]);
  }

  return (
    <ActionsContext.Provider value={actions}>
      <div className="wf">
        <div className="wf-toolbar">
          <div className="wf-toolbar__title">
            <h1>{workflow.title}</h1>
            <label className="visually-hidden" htmlFor="wf-select">워크플로우 선택</label>
            <select
              id="wf-select" className="select wf-select" value={workflow.id}
              onChange={(e) => router.push(`/?workflow=${encodeURIComponent(e.target.value)}`)}
            >
              {workflows.map((w) => <option key={w.id} value={w.id}>{w.title}</option>)}
            </select>
          </div>
          <p className="meta num">카드 {nodes.length}개, 동결 {frozen}개</p>
          <div className="btn-row wf-toolbar__actions">
            {selectedEdges.length > 0 && (
              <button type="button" className="btn btn--ghost btn--danger btn--sm" onClick={() => rf.deleteElements({ edges: selectedEdges })}>
                연결 삭제
              </button>
            )}
            <button type="button" className="btn" id="add-card-btn" aria-expanded={adding} aria-controls="add-card" onClick={() => setAdding((v) => !v)}>
              카드 추가
            </button>
            {frozen > 0 ? (
              <a className="btn btn--primary" href={`${PLAN_DOC}?workflow=${encodeURIComponent(workflow.id)}`}>기획서 만들기</a>
            ) : (
              <button type="button" className="btn btn--primary" disabled aria-describedby="plan-hint">기획서 만들기</button>
            )}
          </div>
          {frozen === 0 && <p className="meta wf-toolbar__hint" id="plan-hint">카드를 하나 이상 동결하면 기획서를 만들 수 있어요.</p>}
        </div>

        {(notice || error) && (
          <div className="wf-notices">
            {notice && <div className="notice" role="status"><Icon name="alert" /><p>{notice}</p></div>}
            {error && (
              <div className="notice notice--error" role="alert">
                <Icon name="alert" /><p>{error}</p>
                <button type="button" className="btn btn--ghost btn--sm wf-notice__close" onClick={() => setError(null)}>닫기</button>
              </div>
            )}
          </div>
        )}

        <div className="wf-canvas" ref={canvasRef}>
          <ReactFlow
            nodes={nodes}
            edges={shownEdges}
            nodeTypes={nodeTypes}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onBeforeDelete={onBeforeDelete}
            onEdgesDelete={onEdgesDelete}
            isValidConnection={(c) => c.source !== c.target}
            deleteKeyCode={['Backspace', 'Delete']}
            fitView
            fitViewOptions={{ padding: 0.15, maxZoom: 1 }}
            minZoom={0.2}
            maxZoom={1.6}
            ariaLabelConfig={ARIA}
          >
            <Background variant={BackgroundVariant.Dots} gap={16} size={1} />
            <Controls showInteractive={false} />
            <MiniMap pannable zoomable nodeClassName={(n) => `mm--${(n as CardNodeT).data.card.status}`} />
          </ReactFlow>
          {nodes.length === 0 && !adding && (
            <div className="wf-overlay">
              <div className="empty"><p>아직 카드가 없어요.</p><button type="button" className="btn" onClick={() => setAdding(true)}>카드 추가</button></div>
            </div>
          )}
          {adding && <AddCardForm onAdd={addCard} onClose={() => setAdding(false)} />}
        </div>
      </div>
    </ActionsContext.Provider>
  );
}

function AddCardForm({ onAdd, onClose }: { onAdd: (title: string, description: string) => Promise<void>; onClose: () => void }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const titleRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    titleRef.current?.focus();
    return () => document.getElementById('add-card-btn')?.focus();
  }, []);

  async function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const title = String(f.get('title') ?? '').trim();
    if (!title) {
      setErr('제목을 써 주세요.');
      titleRef.current?.focus();
      return;
    }
    setBusy(true);
    setErr(null);
    try {
      await onAdd(title, String(f.get('description') ?? '').trim());
      onClose();
    } catch (e2) {
      setErr((e2 as Error).message);
      setBusy(false);
    }
  }

  return (
    <form id="add-card" className="panel wf-add" aria-labelledby="add-card-h" onSubmit={submit} onKeyDown={(e) => e.key === 'Escape' && onClose()} noValidate>
      <header className="panel__head"><h2 className="panel__title" id="add-card-h">카드 추가</h2></header>
      <div className="panel__body wf-add__body">
        <div className="field">
          <label className="field__label" htmlFor="new-title">제목</label>
          <input
            ref={titleRef} className="input" id="new-title" name="title" maxLength={80} placeholder="예: 보스 디자인"
            aria-invalid={err ? true : undefined} aria-describedby={err ? 'new-title-err' : undefined}
          />
          {err && <p className="field__error" id="new-title-err">{err}</p>}
        </div>
        <div className="field">
          <label className="field__label" htmlFor="new-desc">설명</label>
          <textarea className="textarea" id="new-desc" name="description" rows={2} maxLength={400} placeholder="예: 지하 정원 끝에서 만나는 상대 정하기" />
        </div>
      </div>
      <footer className="panel__foot">
        <button type="submit" className="btn" disabled={busy} aria-busy={busy}>추가</button>
        <button type="button" className="btn btn--ghost" onClick={onClose}>닫기</button>
      </footer>
    </form>
  );
}
'use client';
import { memo, useState } from 'react';
import { Handle, Position, type NodeProps } from '@xyflow/react';
import { useActions, type CardNodeT } from './flow';
import { Icon, type IconName } from './icons';
import Chat from './Chat';

const LABEL = { active: '진행중', frozen: '동결', cancelled: '취소' } as const;
const ICON: Record<keyof typeof LABEL, IconName> = { active: 'clock', frozen: 'lock', cancelled: 'slash' };

function CardNode({ id, data }: NodeProps<CardNodeT>) {
  const { card, messages } = data;
  const { toggle, setStatus } = useActions();
  const [busy, setBusy] = useState<null | 'freeze' | 'undo'>(null);
  const titleId = `card-${id}-title`;
  const bodyId = `card-${id}-body`;

  async function run(action: 'freeze' | 'undo') {
    setBusy(action);
    await setStatus(id, action);
    setBusy(null);
  }

  return (
    <article className="panel node" data-status={card.status} data-expanded={card.expanded} aria-labelledby={titleId}>
      <Handle type="target" position={Position.Left} />
      <header className="node__head">
        <div className="node__bar">
          <span className={`status status--${card.status}`}><Icon name={ICON[card.status]} />{LABEL[card.status]}</span>
          <div className="node__actions nodrag nopan">
            {card.status === 'active' && (
              <button type="button" className="btn btn--sm" onClick={() => run('freeze')} disabled={!!busy} aria-busy={busy === 'freeze'}>
                <Icon name="lock" />동결
              </button>
            )}
            <button type="button" className="btn btn--ghost btn--sm" onClick={() => run('undo')} disabled={!!busy} aria-busy={busy === 'undo'}>
              {card.status === 'active' ? <><Icon name="slash" />취소</> : <><Icon name="undo" />되돌리기</>}
            </button>
            <button
              type="button" className="btn btn--ghost btn--icon btn--sm" onClick={() => toggle(id)}
              aria-label={card.expanded ? '카드 접기' : '카드 펼쳐서 대화 보기'} aria-expanded={card.expanded} aria-controls={bodyId}
            >
              <Icon name={card.expanded ? 'collapse' : 'expand'} />
            </button>
          </div>
        </div>
        <h3 className="node__title" id={titleId}>{card.title}</h3>
        {card.description && <p className="node__desc">{card.description}</p>}
        {!card.expanded && card.status === 'frozen' && card.decision && <p className="node__decision">{card.decision}</p>}
        {!card.expanded && <p className="meta num">대화 {messages.length}개</p>}
      </header>
      {card.expanded && (
        <div className="node__body nodrag nopan" id={bodyId}>
          <Chat card={card} messages={messages} />
        </div>
      )}
      <Handle type="source" position={Position.Right} />
    </article>
  );
}

export default memo(CardNode);

'use client';
import { Fragment, useEffect, useRef, useState } from 'react';
import type { Card, Message } from '@/lib/store';
import { extractUrls } from '@/lib/urls';
import { parseBlocks, parseInline } from '@/lib/md';
import { useActions } from './flow';
import { Icon } from './icons';
import Gallery from './Gallery';

const time = (iso: string) => new Date(iso).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' });

function Inline({ line }: { line: string }) {
  return parseInline(line).map((t, i) =>
    t.t === 'text' ? <Fragment key={i}>{t.v}</Fragment>
    : t.t === 'bold' ? <strong key={i}>{t.v}</strong>
    : t.t === 'link' ? <a key={i} href={t.href} target="_blank" rel="noopener noreferrer">{t.v}</a>
    : <a key={i} className="url" href={t.href} target="_blank" rel="noopener noreferrer">{t.href}</a>,
  );
}

function Rich({ text }: { text: string }) {
  return parseBlocks(text).map((b, i) =>
    b.t === 'p' ? (
      <p key={i}>{b.lines.map((l, k) => <Fragment key={k}>{k > 0 && <br />}<Inline line={l} /></Fragment>)}</p>
    ) : b.t === 'ul' ? (
      <ul key={i}>{b.items.map((it, k) => <li key={k}><Inline line={it} /></li>)}</ul>
    ) : (
      <ol key={i}>{b.items.map((it, k) => <li key={k}><Inline line={it} /></li>)}</ol>
    ),
  );
}

function Msg({ m, agentName }: { m: Message; agentName: string }) {
  const stamp = <time className="msg__time num" dateTime={m.created_at} suppressHydrationWarning>{time(m.created_at)}</time>;
  if (m.role === 'user') {
    return (
      <li className="msg msg--user">
        <p className="msg__who"><span className="visually-hidden">나</span>{stamp}</p>
        <div className="msg__body"><Rich text={m.content} /></div>
      </li>
    );
  }
  const urls = extractUrls(m.content);
  return (
    <li className="msg msg--agent">
      <p className="msg__who"><Icon name="agent" />{agentName}{stamp}</p>
      <div className="msg__body"><Rich text={m.content} /></div>
      {urls.length > 0 && <Gallery urls={urls} />}
    </li>
  );
}

export default function Chat({ card, messages }: { card: Card; messages: Message[] }) {
  const { send } = useActions();
  const [text, setText] = useState('');
  const [pending, setPending] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const listRef = useRef<HTMLOListElement>(null);
  const inputId = `msg-${card.id}`;
  const agentName = `${card.title} 에이전트`;

  useEffect(() => {
    const el = listRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages.length, pending]);

  async function submit() {
    const content = text.trim();
    if (!content || pending) return;
    setPending(true);
    setErr(null);
    try {
      const r = await send(card.id, content);
      setText('');
      setNote(r.error ? 'LLM 응답을 받지 못해 기본 답변을 보여 드려요.' : null);
    } catch (e) {
      setErr((e as Error).message);
    } finally {
      setPending(false);
    }
  }

  return (
    <>
      {card.status === 'frozen' && (
        <div className="notice node__verdict">
          <Icon name="lock" />
          <div><p className="node__verdict-label">결정</p><p>{card.decision ?? '결정 내용이 없어요.'}</p></div>
        </div>
      )}
      <ol className="chat node__chat nowheel" ref={listRef} aria-label={`${card.title} 대화`} aria-busy={pending}>
        {messages.length === 0 && <li className="meta">아직 대화가 없어요. 이 카드에서 정할 것을 물어보세요.</li>}
        {messages.map((m) => <Msg key={m.id} m={m} agentName={agentName} />)}
        {pending && (
          <li className="msg msg--agent">
            <p className="msg__who"><Icon name="agent" />{agentName}<span className="visually-hidden">답변을 쓰는 중</span></p>
            <span className="skeleton node__skel" /><span className="skeleton node__skel" />
          </li>
        )}
      </ol>
      {card.status === 'active' ? (
        <form className="composer" onSubmit={(e) => { e.preventDefault(); submit(); }}>
          <label className="visually-hidden" htmlFor={inputId}>메시지</label>
          <textarea
            className="textarea" id={inputId} name="message" rows={1} maxLength={4000} value={text} disabled={pending}
            placeholder="예: 비밀방 아이디어를 더 주세요" onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault();
                submit();
              }
            }}
          />
          <button type="submit" className="btn" disabled={pending || !text.trim()} aria-busy={pending}>보내기</button>
        </form>
      ) : (
        <p className="meta">
          {card.status === 'frozen' ? '동결된 카드는 읽기만 할 수 있어요. 고치려면 되돌리기를 눌러요.' : '취소된 카드예요. 되돌리기를 누르면 다시 대화할 수 있어요.'}
        </p>
      )}
      {err && <div className="notice notice--error" role="alert"><Icon name="alert" /><p>{err}</p></div>}
      {note && <p className="meta" role="status">{note}</p>}
    </>
  );
}
'use client';
import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { hostOf, isImageUrl } from '@/lib/urls';
import { Icon } from './icons';

type Preview = { url: string; kind: 'image' | 'page'; title: string | null; description: string | null; image: string | null; site: string | null; error?: string };

// One request per URL per page load, shared by every gallery that shows it.
const cache = new Map<string, Promise<Preview>>();
function loadPreview(url: string): Promise<Preview> {
  let p = cache.get(url);
  if (!p) {
    const failed: Preview = { url, kind: 'page', title: null, description: null, image: null, site: hostOf(url), error: 'failed' };
    p = fetch(`/api/preview?url=${encodeURIComponent(url)}`)
      .then((r) => (r.ok ? (r.json() as Promise<Preview>) : failed))
      .catch(() => failed);
    cache.set(url, p);
  }
  return p;
}

type Open = (src: string, alt: string, from: HTMLElement) => void;

// The first tile is the visible slide, so it loads right away; the rest wait until scrolled near.
function Img({ src, alt, eager = false }: { src: string; alt: string; eager?: boolean }) {
  const [broken, setBroken] = useState(false);
  if (broken) return <><Icon name="alert" /><span className="visually-hidden">이미지를 불러오지 못했어요</span></>;
  return <img src={src} alt={alt} loading={eager ? 'eager' : 'lazy'} decoding="async" width="640" height="400" onError={() => setBroken(true)} />;
}

// Agent text can carry any URL, including bad percent escapes: never let one throw during render.
function fileName(url: string, host: string): string {
  try {
    const last = new URL(url).pathname.split('/').filter(Boolean).at(-1);
    return last ? decodeURIComponent(last) : host;
  } catch {
    return host;
  }
}

function ImageTile({ url, onOpen, eager }: { url: string; onOpen: Open; eager: boolean }) {
  const host = hostOf(url);
  const name = fileName(url, host);
  return (
    <li className="preview">
      <button type="button" className="preview__link preview__btn" onClick={(e) => onOpen(url, `${host} 이미지 ${name}`, e.currentTarget)}>
        <span className="preview__media"><Img src={url} alt="" eager={eager} /></span>
        <span className="preview__title">이미지 크게 보기</span>
        <span className="preview__site">{host}</span>
      </button>
    </li>
  );
}

function PageTile({ url, eager }: { url: string; eager: boolean }) {
  const [p, setP] = useState<Preview | null>(null);
  useEffect(() => {
    let live = true;
    loadPreview(url).then((r) => live && setP(r));
    return () => {
      live = false;
    };
  }, [url]);
  const host = hostOf(url);
  return (
    <li className="preview" aria-busy={!p}>
      <a className="preview__link" href={url} target="_blank" rel="noopener noreferrer">
        <span className="preview__media">
          {!p ? <span className="skeleton preview__skel" /> : p.image ? <Img src={p.image} alt="" eager={eager} /> : <Icon name="link" />}
        </span>
        {p?.title ? <span className="preview__title">{p.title}</span> : <span className="preview__title preview__title--url">{url}</span>}
        <span className="preview__site">{p?.site ?? host}</span>
      </a>
    </li>
  );
}

const reduceMotion = () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

export default function Gallery({ urls }: { urls: string[] }) {
  const [view, setView] = useState<'slide' | 'grid'>('slide');
  const [pos, setPos] = useState(0);
  const [box, setBox] = useState<{ src: string; alt: string } | null>(null);
  const track = useRef<HTMLUListElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const closeBtn = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!box) return;
    dialog.current?.showModal();
    closeBtn.current?.focus();
  }, [box]);

  const stride = () => {
    const el = track.current;
    const first = el?.firstElementChild as HTMLElement | null;
    return el && first ? first.offsetWidth + parseFloat(getComputedStyle(el).columnGap || '0') : 1;
  };
  const go = (dir: 1 | -1) => track.current?.scrollBy({ left: dir * stride(), behavior: reduceMotion() ? 'auto' : 'smooth' });
  const onScroll = () => {
    const el = track.current;
    if (!el) return;
    const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 2;
    setPos(atEnd ? urls.length - 1 : Math.round(el.scrollLeft / stride()));
  };
  const open: Open = (src, alt, from) => {
    opener.current = from;
    setBox({ src, alt });
  };

  return (
    <section className="gallery nowheel" aria-label="링크 미리보기">
      <div className="gallery__bar">
        <p className="meta num">미리보기 {urls.length}개</p>
        {urls.length > 1 && (
          <div className="seg" role="group" aria-label="보기 방식">
            <button type="button" aria-pressed={view === 'slide'} onClick={() => setView('slide')}>슬라이드</button>
            <button type="button" aria-pressed={view === 'grid'} onClick={() => { setView('grid'); setPos(0); }}>격자</button>
          </div>
        )}
      </div>
      <ul className="gallery__track" data-view={urls.length > 1 ? view : 'grid1'} ref={track} onScroll={view === 'slide' ? onScroll : undefined}>
        {urls.map((u, i) => (isImageUrl(u) ? <ImageTile key={u} url={u} onOpen={open} eager={i === 0} /> : <PageTile key={u} url={u} eager={i === 0} />))}
      </ul>
      {urls.length > 1 && view === 'slide' && (
        <div className="gallery__nav">
          <button type="button" className="btn btn--ghost btn--icon btn--sm" aria-label="이전 미리보기" onClick={() => go(-1)} disabled={pos === 0}><Icon name="prev" /></button>
