S=/private/tmp/claude-501/-Users-jyl-work-repo-ai-agent-live-super-planer/0b348ffc-6a36-4420-b451-05e59d38b9e3/scratchpad; cat > $S/slow.test.mjs <<'EOF'
import net from 'node:net';
import http from 'node:http';
const orig = net.BlockList.prototype.check;
const { fetchPreview } = await import(process.argv[2]);
net.BlockList.prototype.check = function () { return false; }; // let loopback through for this probe only
const srv = http.createServer((req, res) => {
  if (req.url === '/slow') { res.writeHead(200, { 'content-type': 'text/html' }); res.write('<title>x'); setInterval(() => res.write('a'), 500); return; }
  if (req.url === '/big') { res.writeHead(200, { 'content-type': 'text/html' }); res.write('<html><head><title>Big</title></head>'); const chunk = 'x'.repeat(65536); const iv = setInterval(() => { if (!res.write(chunk)) {} }, 1); res.on('close', () => clearInterval(iv)); return; }
  if (req.url.startsWith('/r')) { const n = Number(req.url.slice(2)); res.writeHead(302, { location: n > 0 ? `/r${n - 1}` : '/ok' }); return res.end(); }
  if (req.url === '/ok') { res.writeHead(200, { 'content-type': 'text/html' }); return res.end('<meta property="og:title" content="OK">'); }
  if (req.url === '/to-file') { res.writeHead(302, { location: 'file:///etc/passwd' }); return res.end(); }
});
await new Promise((r, j) => srv.listen(80, '127.0.0.1', r).on('error', j));
const t = async (p) => { const s = Date.now(); try { const r = await fetchPreview('http://127.0.0.1' + p); console.log(p, 'OK', r.title, Date.now() - s, 'ms'); } catch (e) { console.log(p, 'ERR', e.message, Date.now() - s, 'ms'); } };
await t('/slow'); await t('/big'); await t('/r2'); await t('/r3'); await t('/r4'); await t('/to-file');
net.BlockList.prototype.check = orig;
// now with real guard: redirect from "public" hop to loopback is caught at the lookup/assert stage
await t('/ok');
srv.closeAllConnections(); srv.close(); process.exit(0);
EOF
